import six
from abc import ABCMeta
from taf.ue.plugin.mtk.commands.at_command import EFUN
from taf.ue.plugin.mtk.flow.action_verifiable import ActionSequenceVerifiable


@six.add_metaclass(ABCMeta)
class EnableLogging(ActionSequenceVerifiable):

    def __init__(self, at_executor=None,
                 log_filter_command=None,
                 config=None,
                 verifier=None):

        self._at_executor = at_executor
        self._log_filter_command = log_filter_command
        self._config = config
        self._verifier = verifier

    def _generate_command_sequence(self):

        return [EFUN(self._at_executor, EFUN.Status.DISABLE),
                self._log_filter_command]
